def find_frame_rows(input_grid, frame_cols, marker_threshold=2):
    """Find rows that have markers (non-1, non-9 values) in at least threshold frame columns"""
    frame_row_to_markers = {}
    for r in range(len(input_grid)):
        markers_in_frame_cols = [input_grid[r][fc] for fc in frame_cols]
        num_markers = sum(1 for v in markers_in_frame_cols if v not in [1, 9])
